        for c,x in enumerate(grid[r]):
            if x!=0: out[h-1-r][c]=x
    return out"},{"nl":"Copy rows 0, 1, and 2 to rows 9, 8, and 7 respectively, only for a 10-row grid.","code":"def transform(grid):
